#!/usr/bin/env python3
"""Render the deterministic report from independent extracts, never peer values."""
from pathlib import Path
import csv,gzip,json,re
D=Path(__file__).resolve().parent;E=D/'extract'
def jl(name):return[json.loads(x)for x in gzip.decompress((E/name).read_bytes()).decode().splitlines()]
def pct(a,b):return f'{100*a/b:.8f}%'
def num(n):return f'{n:,}'
def main():
    c=json.loads((E/'independent-controls.json').read_text());contract=json.loads((D/'priority-set.json').read_text());p=contract['primary_priority'];rows=jl('native-2024-order-printed_observed_sum.jsonl.gz');alt=contract['native_reported_marks_priority'];co=json.loads((E/'county-priorities.json').read_text());county=list(csv.DictReader((E/'county-2024-order-all_named_votes.csv').open()));auth=list(csv.DictReader((D.parent/'county-turnout.csv').open()));states=list(csv.DictReader((E/'statewide-source-rows.csv').open()));den=json.loads((E/'denominator-reconciliation.json').read_text());peer=json.loads((D/'peer-reconciliation.json').read_text())
    stateurl='https://www.elections.il.gov/electionoperations/ElectionVoteTotals.aspx?ID=9huvqbsiUWA%3D&OfficeType=LpWf6lpbWOfBN3kEuxRi3A%3D%3D'
    nativeurl='https://www.elections.il.gov/Downloads/ElectionOperations/ElectionResults/ByOffice/66/66-120-PRESIDENT%20AND%20VICE%20PRESIDENT-2024GE.csv'
    out=['# Illinois turnout and reporting-volume research','',
    'Observed October 19–20, 2026 UTC. **Primary ranking: 2024 president, the exact recorded votes for Harris, Trump and Kennedy where present in the original native export.** Illinois had no 2024 Senate election. This is a printed-known candidate source scope, not all valid presidential votes or ballots cast. It ranks authority ID plus literal precinct-name observations, not physical/current precincts. Four administrative-only named pools remain unavailable; 15 Kennedy cells in otherwise observed groups remain null. [Official native export]('+nativeurl+'), [official statewide presentation]('+stateurl+').','',
    f'**Exact top-15 share: {num(p["top15_votes"])} / {num(p["denominator"])} = {pct(p["top15_votes"],p["denominator"])}. Exact minimum descending set reaching 80%: {num(p["minimum80_count"])} source observation groups, totaling {num(p["cumulative80_votes"])} / {num(p["denominator"])} = {pct(p["cumulative80_votes"],p["denominator"])}.** The preceding {num(p["preceding_count"])} contribute {num(p["preceding_votes"])} ({pct(p["preceding_votes"],p["denominator"])}); St. Clair authority88, literal `O FALLON 3`, adds523. Integer proof: `5*4,473,789 < 4*5,592,368 <= 5*4,474,312`. Descending order makes this the smallest cardinality for this source scope. The remainder is4,522 contexts with1,118,056 recorded printed-known votes, including four unavailable named pools with no invented candidate zeros. [Full native order](data/turnout/extract/native-2024-order-printed_observed_sum.csv.gz), [complete dispatch contract](data/turnout/priority-set.json).','',
    'The ordered 5,540 priority keys, every one of the10,062 observation keys, complete remainder, all108 authority parents and11,535 full presentation/context references are in the contract. Each constituent identifies original record positions and container/name variants, with a lossless reference to all12 original fields. Every geography outside priority remains in the statewide sums. No county substitution or legal/current-geography approval is implied. [Raw record objects](data/turnout/extract/original-native-records.jsonl.gz), [full original source contexts](data/turnout/extract/source-contexts-2024.jsonl.gz).','',
    '| Rank | Authority ID / literal precinct observation | Known printed votes | Cumulative votes |','| ---: | --- | ---: | ---: |']
    for r in rows[:15]:out.append(f'| {r["rank"]} | {r["authority_name"]} ({r["authority_id"]}) / {r["precinct_name_literal"]} | {num(r["printed_observed_sum"])} | {num(r["cumulative_votes"])} |')
    out+=['',f'Ties use descending exact integer count, then literal authority ID as a string and literal precinct name. Unavailable named pools follow observed numeric zeros and have null rank. A separate observed-mark scope adds generic write-in marks: N={num(alt["denominator"])}; top15={num(alt["top15_votes"])} ({pct(alt["top15_votes"],alt["denominator"])}); minimum{num(alt["minimum80_count"])}; preceding{num(alt["preceding_count"])} / {num(alt["preceding_votes"])}; crossing {alt["crossing_key"]} adds{num(alt["crossing_votes"])} to{num(alt["cumulative80_votes"])}. Remainder{num(alt["remainder_count"])} / {num(alt["remainder_votes"])}. [Complete alternate order](data/turnout/extract/native-2024-order-printed_plus_generic_observed.csv.gz). Generic marks do not establish legal write-in votes, and this comparison proves no robustness of an unavailable legal native ranking.','',
    '**Candidate universe and primary reconciliation.** All27 literal statewide 2024 reporting rows sum5,633,310. The three printed candidates sum5,592,368 and match the native export candidate by candidate;24 additional named rows sum40,942. Native generic write-in case variants sum57,411 (recorded source marks only; no generic category is published for Kane or Morgan, so absent observations stay null and any empty recorded aggregation is separately labeled), leaving16,469 unallocated between source scopes. No rescaling, name/VP merging, CandidateID0 deduplication or allocation of that difference occurs. The statewide table includes raw names such as Rudolph Ware, Mike ter Maat and Melina Abdullah as separate reporting entries;27 source rows are not a claim of27 presidential tickets. Blank party cells remain blank. Historical detail pages identify write-in records but contain no vote allocations; their post-election database dates do not establish legal filing eligibility. [State table]('+stateurl+'), [all raw named rows/parties/percentages/detail links](data/turnout/extract/statewide-source-rows.csv), [40 independently inspected detail records](data/turnout/extract/candidate-detail-metadata.json).','',
    'The [FEC2024 publication](https://www.fec.gov/resources/cms-content/documents/2024presgeresults.pdf), independently re-extracted from its retained original, prints IL West1,569, scattered518 and total5,633,310. Three printed names plus seven other source names contribute5,632,792; the remaining17 state rows sum518. That aggregate agreement permits no alias or running-mate joins. FEC is a separate publication of state-provided returns, not independent underlying vote counting. The [NARA certificate of ascertainment](https://www.archives.gov/files/electoral-college/2024/ascertainment-illinois.pdf) describes the December2,2024 state canvass and certifies elector slates; elector votes are repeated across individual electors and are never summed as extra presidential votes. [Independent PDF text and review](data/turnout/extract/federal-local-evidence-review.json).','',
    '| 2024 statewide literal reporting name | Party literal (empty shown —) | Reported votes |','| --- | --- | ---: |']
    for r in states:
        if r['year']=='2024':out.append(f'| {r["name"]} | {r["party"] or "—"} | {num(int(r["votes"]))} |')
    out+=['','Source minor percentages such as Stein31,023 with `< .01%` are contradictory to the counts. Exact source percentage strings remain in the extraction and are unused for weights. Candidate and category totals use integer counts from source rows, never those percentages.','',
    '**Disjoint hierarchy and native units.** The108 native authority IDs are102 county authorities plus Bloomington104, Chicago105, Danville106, East St. Louis107, Galesburg108 and Rockford110. There is no103rd county. Historical source containers explicitly associate these cities with county IDs64/16/92/88/48/101. The county web presentation combines those city counts; it is a separate aggregation view. For example, Cook county Harris1,447,821 equals suburban authority16 672,122 plus Chicago105 775,699. McLean county Harris44,495 equals clerk authority64 23,261 plus Bloomington104 21,234. Every printed candidate reconciles in all102 counties in all three years, and every county named-candidate sum matches its statewide control. [County candidate source positions](data/turnout/extract/county-candidate-source-rows.csv), [108-authority inventory](data/turnout/extract/authority-inventory.json).','',
    'Six city authorities use both container0 and their county-container ID across 2024 categories. Those are preserved source presentations of the same authority, not six extra vote pools. Four blank-label groups in Lawrence51, Marshall59, Menard65 and Galesburg108 publish only generic/nonvote categories; they are retained as unavailable named pools. Will labels include ballot `STYLE` splits and `FED` labels; Peoria includes `FED ONLY` observations. No aggregation to polling sites, vote centers, wards, VTDs or polygons is invented. `PrecinctName` is the literal source label; there is no separate precinct-ID or voting-method column in these three exports. All central/early/absentee-looking labels remain literal with method unavailable. [Native objects](data/turnout/extract/native-units-2024.jsonl.gz), [schema](data/turnout/source/SCHEMA.md).','',
    'County FIPS use the independently parsed [Census2024 county identifier file](https://www.census.gov/geographies/reference-files/2024/geo/gazetter-file.html), not an authority-ID formula. The current [McLean clerk page](https://mcleancountyil.gov/1218/Polling-Locations) explicitly excludes Bloomington city and warns of precinct-line changes. Current office names/IDs and historical counts therefore do not prove November2026 identity, legal exhaustiveness or geometry compatibility. The [city Chicago proclamation](https://cboeprod.blob.core.usgovcloudapi.net/prod/2024-11/Proclamation%20of%20Official%20Results%20%28November%205%2C%202024%29.pdf) confirms printed totals and its named total1,001,481; the [Bloomington official write-in report](https://bloomingtonelectionsil.gov/wp-content/uploads/2024/11/2024-General-Election-Write-In-Official-Report.pdf) totals204 using some combined ticket labels. These bounded local checks do not allocate the statewide valid write-in universe across native units. Galesburg’s retained official scanned canvass shows genericwrite-in72 rather than named allocation. Local counts and vintages remain source-scoped; no blanket valid-native inference follows.','',
    '**County aggregation sensitivity, kept separate from the primary finer order.** All102 combined county named totals reconcile exactly to5,633,310. Top15 contribute4,423,672 (78.52704715%). The minimum17 contribute4,539,638 (80.58562373%); the first16 contribute4,487,130 (79.65352519%); LaSalle adds52,508. Remainder85counties /1,093,672 votes. Ordered17: Cook, DuPage, Will, Lake, Kane, McHenry, Madison, Winnebago, St. Clair, Sangamon, Champaign, McLean, Peoria, Tazewell, Kendall, Rock Island, LaSalle. The contract expands these to all constituent authority keys; Chicago/Rockford/East St. Louis/Bloomington are never silently omitted or counted again. [Complete102county order](data/turnout/extract/county-2024-order-all_named_votes.csv). The official county selector produces no-information bodies for all six city selections; unchanged-default Adams POST clears grids, so the populated initial Adams GET is used and both observations retained. HTTP200 alone is never evidence of numeric coverage.','',
    '**Actual election comparisons and denominator controls.** The2026 regular ClassII election is November3,2026. The2020 Durbin–Curran Senate contest is this ClassII seat; the2022 Duckworth–Salvi Senate contest is the separate ClassIII seat and recent actual midterm. The2024 comparison is president. [ISBE historical search](https://www.elections.il.gov/electionoperations/votetotalsearch.aspx), [FEC2020 official results](https://www.fec.gov/documents/4227/federalelections2020.pdf), [FEC2022 official results](https://www.fec.gov/documents/5675/federalelections2022.pdf), [ISBE schedule/authority originals and source receipts](data/turnout/source/external-originals.json). Each historical native universe is independently retained and ranked, without joining labels across years.','',
    '| Contest | Printed native votes | Additional statewide named votes | All named source votes | Native generic marks | Ballots cast | Turnout-table “Total Voters” |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for y,label in [('2024','2024 president'),('2022','2022 Senate, ClassIII midterm'),('2020','2020 Senate, same ClassII')]:
        r=c[y];d=den[y];out.append(f'| {label} | {num(r["printed_total"])} | {num(r["state_named_additional"])} | {num(r["state_named_total"])} | {num(r["generic_writein_marks"])} | {num(d["ballots"])} | {num(d["turnout_table_Total_Voters"])} |')
    out+=['','The2020 five printed candidates are Durbin3,278,930; Curran2,319,870; Wilson237,699 (WILLIE WILSON PARTY); Malouf75,673 (LIBERTARIAN); Black56,711 (GREEN). Named write-ins Keely10, Seida6 and Schaal2 are separate from generic2,530. The2022 printed candidates are Duckworth2,329,136 (DEMOCRATIC), Salvi1,701,055 (REPUBLICAN), Redpath68,671 (LIBERTARIAN); named Seida23 and Vlakancic11 are separate from generic1,911. All40 statewide raw name/party/count/detail-link records remain in the source-row CSV. No2024 Senate or nonexistent comparator governor contest is used.','',
    'The [official turnout interface](https://www.elections.il.gov/ElectionOperations/VoterTurnout.aspx?MID=fVf30XCcBCY%3D&T=637204911330922199), selected through observed public events, supplies102 combined county rows plus a statewide control for each year. “Total Voters” is the source field label used as a historical registration sensitivity; the inspected table does not define its snapshot/status fully, so it is not voting-eligible population. The native `Registration` field repeats on candidate/category rows. It is retained once per authority/literal-label observation only for a separate source-field diagnostic, never summed across candidates or assumed identical to the turnout table. Totals are7,210,422 /7,973,061 /7,980,411 in2024/2022/2020, versus the distinct table controls above. Zero native Registration literals do not prove zero registered people. [All306 registration comparisons](data/turnout/extract/registration-source-reconciliation.csv).','',
    'A separate suburban Cook [official post-election report](https://www.cookcountyclerkil.gov/sites/default/files/pdfs/Post-Election%20Report%20%20-%20%20110524.pdf), printedpage5, reports2024 Early Voting451,654; Grace Period/In-Person Absentee14,742; Mail Voting192,412; Election Day431,134, totaling1,089,942ballots. These method volumes are separately retained with2020 comparisons and reconcile; they are not presidential candidate counts, statewide method coverage or a live remaining-vote estimate. [Source-scoped local method controls](data/turnout/extract/local-ballot-method-controls.json). Candidate votes are not ballots. In2024 ballots exceed all named source votes by71,936. Native published nonvote categories sum Under Votes47,666 / Over Votes4,821 / Blank Ballots510, with absence left null outside rows that actually publish them. Printed votes + generic marks + all these native categories total5,702,776, which remains2,470 below the separate ballot control5,705,246. This residual is unallocated, not labeled as extra undervotes, blank ballots or valid write-ins. Senate2022 and2020 native exports contain no under/over/blank categories; the corresponding ballots-minus-all-native-category differences43,352 and127,316 are denominator gaps, not observed nonvote allocations. [Exact reconciliation](data/turnout/extract/denominator-reconciliation.json), [literal category totals](data/turnout/extract/native-category-controls.csv).','',
    'The [current registration page](https://www.elections.il.gov/VotingAndRegistrationSystems/RegistrationCounts.aspx) describes unofficial jurisdiction-supplied statewide-database counts that fluctuate daily and prints10/19/2026 10:18AM (timezone unstated). Its actual linked CSV contains108 IDs and literal columns`A` and`I`, summing8,306,489 and730,052. These literal category letters are retained; the inspected CSV/page does not itself expand their definitions. They are not historical ballots, an approved boundary join, or a2026 turnout forecast. The compatibility CSV retains the exact current source fields and clock separately from historical counts.','',
    '| Separate county sensitivity | Denominator | Top15 count volume/share | Minimum80 count | Preceding cumulative | Crossing cumulative |','| --- | ---: | --- | ---: | ---: | ---: |']
    for y,field,label in [('2024','all_named_votes','2024 named presidential votes'),('2024','printed_votes','2024 printed presidential votes'),('2024','printed_plus_generic_marks','2024 printed+generic marks'),('2024','ballots_cast','2024 ballots'),('2024','historical_Total_Voters','2024 Total Voters field'),('2022','all_named_votes','2022 named Senate votes'),('2022','ballots_cast','2022 ballots'),('2020','all_named_votes','2020 named Senate votes')]:
        r=co[y+':'+field];out.append(f'| {label} | {num(r["denominator"])} | {num(r["top15_votes"])} / {pct(r["top15_votes"],r["denominator"])} | {r["minimum80_count"]} | {num(r["preceding_votes"])} | {num(r["cumulative80_votes"])} |')
    out+=['',f'The2022 named Senate volume is{pct(c["2022"]["state_named_total"],c["2024"]["state_named_total"])} of2024 named presidential volume. Historical changes mix candidate/contest/year effects with participation. These are volume/denominator sensitivity anchors with complete statewide weights, not low/base/high2026 forecasts. Full orders for every listed scope/year are retained; no unavailable native voting-method distribution is invented.','',
    f'**Reproduction and QA.** `build_turnout.py` independently parses original state bodies, `enrich_evidence.py` re-extracts primary PDFs/detail metadata, `compare_peer.py` freezes immutable reciprocal captures, `write_report.py` generates this report, and `validate_turnout.py --seal` checks and seals the owned assets. Run these offline in that order, using Python3 with beautifulsoup4 and Poppler; acquisition separately requires requests. Own reciprocal reconciliation: **{num(peer["checks"])} checks,0errors**. It compares all146,370rawrecords×12fields+positions,306countycontrols,1462literal candidate rows, native candidates/missingness/categories/registration/contexts, all108authority categories/year, full county orders/integer80 and native printed order. Only the explicit placement of four unavailable named pools after observed zeros differs from the peer’s empty-recorded-sum ordering; both immutable raw captures remain. [Reciprocal evidence](data/turnout/peer-reconciliation.json), [offline validation](data/turnout/validation.json), [owned asset manifest](data/turnout/asset-manifest.json), [source schema](data/turnout/source/SCHEMA.md).','',
    'Every numeric-source original is retained losslessly below40,000,000stored bytes, or referenced read-only by exact original/stored SHA256 and size. Complete response headers, requested/final URLs, parent chains, public form fields, redirects, UTC and source clocks live in receipts. Shared original news and peer primary bodies are references, not numeric derivative dependencies. All unrelated offices in downloaded county pages remain in original bytes; no extra demographic extraction is required. No live collector, measured November cadence, calibrated Needle, current precinct approval or complete legal-native write-in universe is claimed. Coordinator acceptance remains pending.','',
    '**Complete108-authority reported-mark order (secondary scope).** This table uses printed-known+generic recorded marks only (N5,649,779), preserving commission boundaries. It does not replace the primary finer order or claim a legal named-vote ranking. Its top15=4,290,100 /5,649,779; minimum20=4,555,873; preceding19=4,508,088; Kankakee46 crosses; remainder88=1,093,906. The compatibility filename`county-turnout.csv` contains these108authorities, never102substituted counties. [Full machine table](data/county-turnout.csv).','',
    '| Rank | Actual authority (ID) | Parent county FIPS | Reported printed+generic marks | Cumulative |','| ---: | --- | --- | ---: | ---: |']
    for r in auth:out.append(f'| {r["rank"]} | {r["authority_name"]} ({r["authority_id"]}) | {r["county_fips"]} | {num(int(r["president_2024_printed_plus_generic_marks"]))} | {num(int(r["cumulative_votes"]))} |')
    out+=['','**Complete102county named-vote aggregation order (separate sensitivity).** City observations are already inside these totals and are not added again. The native primary order and remainder remain in the linked full-order files above.','',
    '| Rank | County / FIPS | Named votes2024 | Cumulative | Senate named votes2022 | Ballots2024 |','| ---: | --- | ---: | ---: | ---: | ---: |']
    comp={r['county_authority_id']:r for r in csv.DictReader((E/'county-2022-order-all_named_votes.csv').open())}
    for r in county:out.append(f'| {r["rank"]} | {r["county_name"]} / {r["county_fips"]} | {num(int(r["all_named_votes"]))} | {num(int(r["cumulative_votes"]))} | {num(int(comp[r["county_authority_id"]]["all_named_votes"]))} | {num(int(r["ballots_cast"]))} |')
    def prose_spaces(text):
        # Preserve exact URLs, source labels in code, and Markdown targets.
        parts=re.split(r'(\[[^\]]*\]\([^\n]*?\)|`[^`]*`|https?://\S+)',text)
        for i in range(0,len(parts),2):
            parts[i]=re.sub(r'([A-Za-z])(\d)',r'\1 \2',parts[i])
            parts[i]=re.sub(r'(\d)([A-Za-z])',r'\1 \2',parts[i])
            parts[i]=parts[i].replace('ClassIII','Class III').replace('ClassII','Class II')
        return ''.join(parts)
    (D.parent.parent/'turnout.md').write_text(prose_spaces('\n'.join(out))+'\n')
if __name__=='__main__':main()
